 "content": "def transform(grid):
    """Restore rectangular color patches; discard isolated stray marks."""
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(x == v for row in grid for x in row))
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            if len(cells) >= 4:
                objects.append((color, min(x for x, y in cells), max(x for x, y in cells),
                                min(y for x, y in cells), max(y for x, y in cells)))
    out = [[bg] * w for _ in range(h)]
    for color, r0, r1, c0, c1 in objects:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color
    return out

if __name__ == '__main__':
    import json
    print(json.dumps(transform(json.loads(input()))))
